// The lightbox's math, framework-free: geometry (fit, source view, stage band), the
// gesture rules (zoom at a point, rubber, pan bounds, momentum, commit tests) and one
// interruptible spring. Numbers in, numbers out; the component owns the DOM and the
// clock. `bun scripts/examples/lightbox-motion.ts` exercises every invariant.

export type View = { x: number; y: number; s: number }
/** The view plus `p`, how far the room is lit: 0 at the source, 1 at rest. */
export type Pose = View & { p: number }
export type Size = { w: number; h: number }
export type Rect = {
  x: number
  y: number
  w: number
  h: number
  radius: number
}
export type Band = { top: number; left: number; w: number; h: number }
export type Point = { x: number; y: number }
export type Tuning = { zeta: number; f: number }
/** One tuning for every axis, or one per axis: a flick that coasts on x while y
 *  bounces off a wall runs COAST and MACHINE side by side. */
export type Tunings<K extends string> = Tuning | Readonly<Record<K, Tuning>>

export function assert(cond: unknown, msg: string): asserts cond {
  if (!cond) throw new Error(`lightbox: ${msg}`)
}

/** Machine moves: enter, exit, zoom, pan recovery, step. */
export const MACHINE: Tuning = { zeta: 1, f: 4.5 }
/** Hand releases: dismiss cancel, slide commit. A little weight. */
export const HAND: Tuning = { zeta: 0.82, f: 4.5 }
/** A key step: brisk, the reader already knows where they are going. */
export const QUICK: Tuning = { zeta: 1, f: 7 }
/** Reduced motion: the target is assumed at once. */
export const STILL: Tuning = { zeta: 1, f: Infinity }

export const FIT: View = { x: 0, y: 0, s: 1 }
/** Exit target when the trigger left the page: a cut, never an abort. */
export const GONE: View = { x: 0, y: 0, s: 0.92 }

export const SLIDE_GAP = 32
export const MOMENTUM = 199
/** A free coast after a flick: the projected rest is `v · MOMENTUM` away, and a
 *  critically damped spring whose ω = 1/MOMENTUM is the exact exponential decay that
 *  projection assumes, so the hand's velocity is never exceeded. A stiffer spring
 *  aimed that far away accelerates first (2.1x the release speed with MACHINE). */
export const COAST: Tuning = { zeta: 1, f: 1000 / (2 * Math.PI * MOMENTUM) }
export const INTENT = 6
export const RELOCK = 12
export const OVERSHOOT = 0.35
export const TAP_TRAVEL = 4
export const DISMISS_COMMIT = 0.4
export const PINCH_CLOSE = 0.75
export const PINCH_PASSED = 1.067
export const SLIDE_VELOCITY = 0.5
/** A held arrow pans at this speed (px per ms); two arrows add up to a diagonal. */
export const KEY_PAN_SPEED = 0.9
/** A held + or - doubles (halves) the zoom every this many ms. */
export const KEY_ZOOM_MS = 700
export const WHEEL_GUARD = 400
export const WHEEL_ZOOM = 0.01
/** One wheel event moves at most this many px: a mouse notch (100 px in Chrome) is a
 *  nudge, a trackpad tick (1-30 px) is untouched. Bounds ctrl+wheel zoom to 1.35x. */
export const WHEEL_TICK_MAX = 30
/** A finger still for this long before lifting has no momentum. */
export const STOP_GAP = 50
/** Release velocity is the mean over this span; a gesture keeps SAMPLES points,
 *  enough to cover it at 120 Hz. */
export const VELOCITY_WINDOW = 100
export const SAMPLES = 12
/** Flights are sampled ahead at this period; a compositor plays the table. */
export const FLIGHT_DT = 1000 / 60
export const DOUBLE_TOUCH = 300
export const DOUBLE_MOUSE = 500
export const DOUBLE_TRAVEL = 24
export const SETTLE_LIMIT = 2000
export const MAX_DT = 32

const clamp = (v: number, lo: number, hi: number) =>
  Math.min(hi, Math.max(lo, v))

/** A media box is finite and positive on both axes; anything else is a lie. */
export function assertSize(size: Size): void {
  assert(
    Number.isFinite(size.w) && size.w > 0,
    `width must be finite > 0, got ${size.w}`,
  )
  assert(
    Number.isFinite(size.h) && size.h > 0,
    `height must be finite > 0, got ${size.h}`,
  )
}

/** Contain `natural` inside `band` less `inset` on every side, never upscaled. */
export function fit(natural: Size, band: Band, inset = 0): Size {
  assertSize(natural)
  const k = Math.min(
    1,
    (band.w - 2 * inset) / natural.w,
    (band.h - 2 * inset) / natural.h,
  )
  return { w: natural.w * k, h: natural.h * k }
}

export type SourceView = {
  view: View
  /** Local-px inset that turns the fit box into the trigger's cover crop. */
  clip: Size
  /** Local-px corner radius matching the trigger's. */
  radius: number
}

/** The view that lays the fit box over the trigger's live rect, cover-fashion. `view`
 *  is relative to the band center; clip and radius are in the layer's own px (before
 *  scale). Identity when the aspects match: clip is zero. */
export function sourceView(rect: Rect, fitted: Size, band: Band): SourceView {
  assert(rect.w > 0 && rect.h > 0, "trigger has a zero rect")
  const cover = Math.max(rect.w / fitted.w, rect.h / fitted.h)
  return {
    view: {
      x: rect.x + rect.w / 2 - (band.left + band.w / 2),
      y: rect.y + rect.h / 2 - (band.top + band.h / 2),
      s: cover,
    },
    clip: {
      w: (fitted.w * cover - rect.w) / 2 / cover,
      h: (fitted.h * cover - rect.h) / 2 / cover,
    },
    radius: rect.radius / cover,
  }
}

/** Rescale so the point `at` (relative to the band center) stays under the finger. */
export function zoomAt(view: View, s: number, at: Point): View {
  const k = s / view.s
  return { x: at.x - (at.x - view.x) * k, y: at.y - (at.y - view.y) * k, s }
}

/** Zoom rubber: soft under `min`, stiff over `max`. */
export function rubber(raw: number, min: number, max: number): number {
  if (raw < min) return min - 0.15 * (min - raw)
  if (raw > max) return max + 0.05 * (raw - max)
  return raw
}

/** Pan bound per axis: half the overflow of the scaled fit past the band. */
export function panBounds(view: View, fitted: Size, band: Band): Point {
  return {
    x: Math.max(0, (fitted.w * view.s - band.w) / 2),
    y: Math.max(0, (fitted.h * view.s - band.h) / 2),
  }
}

/** Pan overshoot while the finger is down: the excess past the bound × 0.35. */
export function overshoot(value: number, bound: number): number {
  if (value > bound) return bound + (value - bound) * OVERSHOOT
  if (value < -bound) return -bound + (value + bound) * OVERSHOOT
  return value
}
/** The exact inverse: a grab taken past the bound (mid-bounce, or a rubbered wheel
 *  pan) is read back to the raw offset it rubbered from, so a drag that offsets the
 *  raw grab and rubbers the sum is continuous at dx = 0. */
export function unovershoot(value: number, bound: number): number {
  if (value > bound) return bound + (value - bound) / OVERSHOOT
  if (value < -bound) return -bound + (value + bound) / OVERSHOOT
  return value
}

export function clampPan(view: View, fitted: Size, band: Band): View {
  const b = panBounds(view, fitted, band)
  return { x: clamp(view.x, -b.x, b.x), y: clamp(view.y, -b.y, b.y), s: view.s }
}

/** A grab's pan read back through the rubber: the raw offset a session adds its
 *  deltas to before rubbering the sum (see `unovershoot`). */
export function rawPan(view: View, fitted: Size, band: Band): Point {
  const b = panBounds(view, fitted, band)
  return { x: unovershoot(view.x, b.x), y: unovershoot(view.y, b.y) }
}

/** Where a flick comes to rest on its own. */
export function project(position: number, velocity: number): number {
  return position + velocity * MOMENTUM
}

/** A wheel event's delta in px: lines and pages become px. Unbounded, so the inertia
 *  guard sees the tick the device sent. */
export function wheelPx(
  delta: number,
  deltaMode: number,
  pageH: number,
): number {
  const k = deltaMode === 1 ? 16 : deltaMode === 2 ? pageH : 1
  return delta * k
}
/** One tick's motion: bounded, so a mouse notch is a nudge. */
export function wheelTick(px: number): number {
  return clamp(px, -WHEEL_TICK_MAX, WHEEL_TICK_MAX)
}

/** Vertical dismiss drag at fit: the room re-lights over a third of the viewport. */
export function dragScale(y: number, vh: number): number {
  return 1 - 0.2 * Math.min(1, Math.abs(y) / (vh / 3))
}
export function dragProgress(y: number, vh: number): number {
  return 1 - Math.min(1, Math.abs(y) / (vh / 3))
}
/** Pinch under fit: the room is fully out at s = 1/1.2. */
export function pinchProgress(s: number): number {
  return clamp(1 - (1 - s) * 1.2, 0, 1)
}

export function dismissCommit(y: number, vy: number, vh: number): boolean {
  return Math.abs(project(y, vy)) / (vh / 3) > DISMISS_COMMIT
}

/** Which neighbours exist around `index`: every wrap rule in one place. */
export function neighbours(
  index: number,
  count: number,
  loop: boolean,
): { prev: boolean; next: boolean } {
  assert(index >= 0 && index < count, `index ${index} of ${count}`)
  return { prev: loop || index > 0, next: loop || index < count - 1 }
}

/** −1 (previous), 1 (next) or 0 (spring home). A fast release decides by velocity:
 *  toward the offset it commits, against it the hand is going home, whatever the
 *  distance. A slow release decides by distance alone. `can` says which
 *  neighbours exist. */
export function slideCommit(
  slideX: number,
  vx: number,
  bandW: number,
  can: { prev: boolean; next: boolean },
): -1 | 0 | 1 {
  const fast = Math.abs(vx) > SLIDE_VELOCITY
  const far = Math.abs(slideX) > 0.5 * bandW
  if (fast) {
    if (slideX !== 0 && Math.sign(vx) !== Math.sign(slideX)) return 0
  } else if (!far) return 0
  const dir: -1 | 1 = (fast ? vx : slideX) < 0 ? 1 : -1
  return (dir === 1 ? can.next : can.prev) ? dir : 0
}

export type Sample = Point & { t: number }

/** Mean velocity (px/ms) over the samples inside VELOCITY_WINDOW, measured against
 *  the release instant `now`. The release is NOT a sample: a mouse button lifts tens
 *  of ms after the hand's last motion, and a release point duplicating the last
 *  move would halve the speed. A hand that rested longer than STOP_GAP before `now`,
 *  or before its own last sample, has stopped and carries nothing. */
export function velocity(samples: readonly Sample[], now: number): Point {
  const recent = samples.filter((s) => now - s.t <= VELOCITY_WINDOW)
  if (recent.length < 2) return { x: 0, y: 0 }
  const a = recent[0] as Sample
  const b = recent[recent.length - 1] as Sample
  const before = recent[recent.length - 2] as Sample
  if (now - b.t > STOP_GAP || b.t - before.t > STOP_GAP) return { x: 0, y: 0 }
  const dt = Math.max(1, b.t - a.t)
  return { x: (b.x - a.x) / dt, y: (b.y - a.y) / dt }
}

/** The zoom ceiling: never under 2, otherwise the source's native pixels at this DPR. */
export function zoomMax(naturalW: number, fitW: number, dpr: number): number {
  return Math.max(2, naturalW / (fitW * dpr))
}

/** The scale at which the source runs out of pixels. Under 2 means source-limited. */
export function sharpScale(
  naturalW: number,
  fitW: number,
  dpr: number,
): number {
  return naturalW / (fitW * dpr)
}

/** A wheel session is a hand only if its first three ticks are not monotonically
 *  decaying in magnitude; inertia only ever decays. */
export function wheelIsHand(ticks: readonly number[]): boolean {
  assert(ticks.length >= 3, "wheel guard needs three ticks")
  const [a, b, c] = ticks as [number, number, number]
  return !(a > b && b > c)
}

export type Obstruction = { side: "top" | "bottom"; edge: number }

/** The stage: the visual viewport minus declared chrome. `edge` is the obstruction's
 *  inner edge in viewport coordinates (a top bar's bottom, a bottom bar's top). */
export function stageBand(vv: Band, blocks: readonly Obstruction[]): Band {
  let top = vv.top
  let bottom = vv.top + vv.h
  for (const b of blocks) {
    if (b.side === "top") top = Math.max(top, b.edge)
    else bottom = Math.min(bottom, b.edge)
  }
  assert(bottom > top, "obstructions cover the whole viewport")
  return { top, left: vv.left, w: vv.w, h: bottom - top }
}

export type Axes<K extends string> = Readonly<Record<K, number>>

const zero = <K extends string>(like: Axes<K>): Axes<K> =>
  Object.fromEntries(Object.keys(like).map((k) => [k, 0])) as Axes<K>

const isTuning = (t: Tunings<string>): t is Tuning => "zeta" in t
const tuningOf = <K extends string>(t: Tunings<K>, k: K): Tuning =>
  isTuning(t) ? t : t[k]

/** One step of a damped spring on every axis, in px and ms: the velocity unit is
 *  the one gestures measure and momentum projects. The closed-form solution of the
 *  oscillator, exact at any frame period, so a device holding 30 fps gets the same
 *  curve as one at 120. MAX_DT is a per-frame progress cap, not a stability limit.
 *  Pure. */
export function springStep<K extends string>(
  value: Axes<K>,
  vel: Axes<K>,
  target: Axes<K>,
  tuning: Tunings<K>,
  dtMs: number,
): { value: Axes<K>; vel: Axes<K> } {
  const dt = Math.min(dtMs, MAX_DT)
  const nv: Record<string, number> = {}
  const nx: Record<string, number> = {}
  for (const k of Object.keys(value) as K[]) {
    const tu = tuningOf(tuning, k)
    if (tu.f === Infinity) {
      nx[k] = target[k]
      nv[k] = 0
      continue
    }
    assert(tu.zeta >= 0 && tu.zeta <= 1, `zeta ${tu.zeta} out of [0, 1]`)
    const w = (2 * Math.PI * tu.f) / 1000
    const z = tu.zeta
    const e = Math.exp(-z * w * dt)
    const d0 = value[k] - target[k]
    const v0 = vel[k]
    let d: number
    let v: number
    if (z === 1) {
      const c = v0 + w * d0
      d = (d0 + c * dt) * e
      v = (v0 - c * w * dt) * e
    } else {
      const wd = w * Math.sqrt(1 - z * z)
      const b = (v0 + z * w * d0) / wd
      const cos = Math.cos(wd * dt)
      const sin = Math.sin(wd * dt)
      d = e * (d0 * cos + b * sin)
      v = e * ((wd * b - z * w * d0) * cos - (wd * d0 + z * w * b) * sin)
    }
    nx[k] = target[k] + d
    nv[k] = v
  }
  return { value: nx as Axes<K>, vel: nv as Axes<K> }
}

export function settled<K extends string>(
  value: Axes<K>,
  vel: Axes<K>,
  target: Axes<K>,
  eps: Axes<K>,
): boolean {
  for (const k of Object.keys(value) as K[]) {
    if (Math.abs(value[k] - target[k]) >= eps[k]) return false
    if (Math.abs(vel[k]) >= eps[k] * 0.02) return false
  }
  return true
}

/** The one clock. Holds the live value, a target and a tuning; `step` advances by a
 *  frame and answers whether it settled. A spring that has not settled within
 *  SETTLE_LIMIT ms screams: a stuck phase is a bug, never a wait. */
export class Spring<K extends string> {
  value: Axes<K>
  vel: Axes<K>
  target: Axes<K>
  tuning: Tunings<K> = MACHINE
  /** Integrated time since the last aim, capped per frame the way the step is. */
  elapsed = 0
  readonly eps: Axes<K>

  constructor(value: Axes<K>, eps: Axes<K>) {
    this.value = value
    this.vel = zero(value)
    this.target = value
    this.eps = eps
  }

  /** Retarget mid-flight; velocity carries over unless handed a new one. */
  aim(target: Axes<K>, tuning: Tunings<K>, vel?: Axes<K>): void {
    this.target = target
    this.tuning = tuning
    if (vel) this.vel = vel
    this.elapsed = 0
  }

  /** Drop the clock at the current value (a hand took over). */
  hold(): void {
    this.target = this.value
    this.vel = zero(this.value)
  }

  step(dtMs: number): boolean {
    const next = springStep(
      this.value,
      this.vel,
      this.target,
      this.tuning,
      dtMs,
    )
    this.value = next.value
    this.vel = next.vel
    this.elapsed += Math.min(dtMs, MAX_DT)

    const done = settled(this.value, this.vel, this.target, this.eps)
    if (done) {
      this.value = this.target
      this.vel = zero(this.value)
    }
    assert(
      done || this.elapsed <= SETTLE_LIMIT,
      `spring stuck: ${this.elapsed.toFixed(0)} ms without settling`,
    )
    return done
  }
}

export type Frame<K extends string> = {
  t: number
  value: Axes<K>
  vel: Axes<K>
}

/** The whole flight ahead of time: the spring is deterministic, so it is sampled at
 *  FLIGHT_DT until it settles and the table is handed to the compositor. Frame 0 is
 *  the start; the last frame is the target exactly. A stuck spring screams here. */
export function sampleFlight<K extends string>(
  value: Axes<K>,
  vel: Axes<K>,
  target: Axes<K>,
  tuning: Tunings<K>,
  eps: Axes<K>,
): Frame<K>[] {
  const s = new Spring<K>(value, eps)
  s.aim(target, tuning, vel)
  const frames: Frame<K>[] = [{ t: 0, value, vel }]
  let t = 0
  for (;;) {
    const done = s.step(FLIGHT_DT)
    t += FLIGHT_DT
    frames.push({ t, value: s.value, vel: s.vel })
    if (done) break
  }
  return frames
}

/** The pose and velocity at `t` ms into a sampled flight, interpolated between
 *  frames; clamped to the table's ends. */
/** WebKit keeps animation time in seconds and converts back to milliseconds, so a
 *  finished animation's currentTime comes back a hair under the duration it was
 *  given (583.33333333333314 for 583.33333333333337). Times within this of the last
 *  frame ARE the last frame. */
export const TIME_EPS = 1e-3

export function frameAt<K extends string>(
  frames: readonly Frame<K>[],
  t: number,
): Frame<K> {
  assert(frames.length >= 2, "a flight has at least two frames")
  assert(Number.isFinite(t), `a flight time that is not a number: ${t}`)
  const last = frames[frames.length - 1] as Frame<K>
  if (t >= last.t - TIME_EPS) return last
  if (t <= 0) return frames[0] as Frame<K>
  const i = Math.min(frames.length - 2, Math.floor(t / FLIGHT_DT))
  const a = frames[i] as Frame<K>
  const b = frames[i + 1] as Frame<K>
  const k = (t - a.t) / (b.t - a.t)
  const lerp = (p: Axes<K>, q: Axes<K>): Axes<K> =>
    Object.fromEntries(
      Object.keys(p).map((key) => [
        key,
        p[key as K] + (q[key as K] - p[key as K]) * k,
      ]),
    ) as Axes<K>
  return { t, value: lerp(a.value, b.value), vel: lerp(a.vel, b.vel) }
}

// A flight: a spring sampled into a frame table, played on the compositor as a Web
// Animation and read back through that animation's own clock. The binder owns the
// DOM (it creates the animations and cancels them); this module owns the table, the
// clock read and the landing rule. Framework-free: the clock is anything with a
// `currentTime`. `bun scripts/examples/lightbox-flight.ts` exercises it.

import {
  type Axes,
  assert,
  type Frame,
  frameAt,
  sampleFlight,
  TIME_EPS,
  type Tunings,
} from "@/registry/base-nova/lib/lightbox-motion"

/** What a Web Animation looks like from here: a clock in ms. */
export type Clock = { readonly currentTime: unknown }

export type Flight<K extends string> = {
  frames: Frame<K>[]
  target: Axes<K>
  /** Reaching `target` is the pending checkpoint (settle the enter, close, clear
   *  pending); a flight that merely returns the image to a grab is not. */
  settles: boolean
  clock: Clock
}

/** The table and its duration: the two things the animation is built from. */
export function planFlight<K extends string>(
  value: Axes<K>,
  vel: Axes<K>,
  target: Axes<K>,
  tuning: Tunings<K>,
  eps: Axes<K>,
): { frames: Frame<K>[]; duration: number } {
  const frames = sampleFlight(value, vel, target, tuning, eps)
  return { frames, duration: lastFrame(frames).t }
}

const lastFrame = <K extends string>(frames: readonly Frame<K>[]): Frame<K> => {
  assert(frames.length >= 2, "a flight has at least two frames")
  return frames[frames.length - 1] as Frame<K>
}

/** The animation's clock in ms. Screams on anything that is not a finite number: a
 *  null clock is a flight whose animation was never started or already cancelled. */
export function flightTime<K extends string>(f: Flight<K>): number {
  const t = f.clock.currentTime
  assert(
    typeof t === "number" && Number.isFinite(t),
    `flight without a clock: ${String(t)}`,
  )
  return t
}

/** Landed: the clock reached the last frame. WebKit hands the duration back a hair
 *  short (seconds in, milliseconds out), so "reached" is within TIME_EPS. */
export function flightDone<K extends string>(
  f: Flight<K>,
  now: number,
): boolean {
  return now >= lastFrame(f.frames).t - TIME_EPS
}

/** The frame under the clock (pose and velocity, for a takeover or a tick) and
 *  whether the flight has landed. */
export function readFlight<K extends string>(
  f: Flight<K>,
): { frame: Frame<K>; done: boolean } {
  const now = flightTime(f)
  return { frame: frameAt(f.frames, now), done: flightDone(f, now) }
}

// The hold loop: a key held while zoomed drives the image at a constant rate until
// keyup. Arrows pan, every held arrow adding its axis, so up + left is a diagonal;
// + and - zoom about the center, doubling every KEY_ZOOM_MS. One glide, not a spring
// restarted on every repeat. Framework-free: the binder owns the rAF loop and the
// key tracking, this module turns the set of held verbs and a frame's dt into a
// view. `bun scripts/examples/lightbox-hold.ts` exercises it.

import {
  type Band,
  clampPan,
  KEY_PAN_SPEED,
  KEY_ZOOM_MS,
  MAX_DT,
  type Size,
  type View,
  zoomAt,
} from "@/registry/base-nova/lib/lightbox-motion"

/** The action ids a key can hold; a subset of the action table's ids. */
export type HoldVerb =
  | "pan.left"
  | "pan.right"
  | "pan.up"
  | "pan.down"
  | "zoom.in"
  | "zoom.out"

export type HoldDelta = {
  /** Pan in px, image-space: left pushes the image right. */
  dx: number
  dy: number
  /** Zoom factor; 1 when no zoom key is held. */
  k: number
}

/** What one frame of `dt` ms adds for the verbs held. Axes add; opposite arrows
 *  cancel. dt is capped at MAX_DT so a frame lost to a tab switch never slingshots. */
export function holdDelta(held: Iterable<HoldVerb>, dt: number): HoldDelta {
  const ms = Math.min(dt, MAX_DT)
  let dx = 0
  let dy = 0
  let k = 1
  for (const id of held) {
    switch (id) {
      case "pan.left":
        dx += KEY_PAN_SPEED * ms
        break
      case "pan.right":
        dx -= KEY_PAN_SPEED * ms
        break
      case "pan.up":
        dy += KEY_PAN_SPEED * ms
        break
      case "pan.down":
        dy -= KEY_PAN_SPEED * ms
        break
      case "zoom.in":
        k *= 2 ** (ms / KEY_ZOOM_MS)
        break
      case "zoom.out":
        k /= 2 ** (ms / KEY_ZOOM_MS)
        break
      default: {
        const never: never = id
        throw new Error(`lightbox: not a hold verb ${String(never)}`)
      }
    }
  }
  return { dx, dy, k }
}

/** The view after one frame of hold: the zoom is applied about the center and held
 *  between 1 and `zoomMax`, the pan is added, and the result is clamped to the
 *  band so a held arrow stops at the edge instead of rubbering. */
export function applyHold(
  view: View,
  delta: HoldDelta,
  fitted: Size,
  band: Band,
  zoomMax: number,
): View {
  const s = Math.min(zoomMax, Math.max(1, view.s * delta.k))
  const zoomed = delta.k === 1 ? view : zoomAt(view, s, { x: 0, y: 0 })
  return clampPan(
    { ...zoomed, x: zoomed.x + delta.dx, y: zoomed.y + delta.dy },
    fitted,
    band,
  )
}

// Which part of a wheel stream is the HAND and which is the device coasting.
//
// The web never says when fingers leave a trackpad. Every carousel that accumulates
// wheel deltas past a threshold gets this wrong the same way: momentum keeps filling
// the accumulator long after the reader meant to stop, so one flick pages four times.
// The signal that does exist is in the shape of the decay. Inertia is generated by a
// physics model, so each velocity is a near-constant fraction of the one before it;
// a hand is never that regular. Five merged points whose acceleration factor all sit
// in [ACC_MIN, ACC_MAX] (or which decay at EXACTLY the same rate on both axes, which
// only a model does) are the device, not a person.
//
// Vendored from wheel-gestures by Felix Leupold (xiel), MIT, the detector behind
// Embla's wheel plugin: github.com/xiel/wheel-gestures. Reduced to two axes and one
// pure function, our constants kept at his measured values. Numbers in, phase out.
// `bun scripts/examples/lightbox-wheel-phase.ts`.

import type { Point } from "@/registry/base-nova/lib/lightbox-motion"

/** A decaying velocity ratio inside this band is a physics model coasting. Outside
 *  it, something is pushing. */
export const ACC_MIN = 0.6
export const ACC_MAX = 0.96
/** Events are averaged in pairs before velocity: one raw wheel event is too noisy to
 *  take a ratio of. */
export const MERGE = 2
/** How many consecutive merged points must agree before we believe it is momentum. */
export const ANALYZE = 5
/** No single event moves more than this; a device reporting more is lying. */
export const DELTA_MAX = 700
/** Before the first two events time the stream, assume a slow mouse: a long window,
 *  so an old device emitting rarely still reads as one continuous gesture. */
export const ENDS_IN_DEFAULT = 400
export const ENDS_IN_MAX = 1000
/** Momentum is cut short by a delta this many times the last one: the hand is back. */
export const HAND_RETURN = 2

export type Wheel = { dx: number; dy: number; t: number }

export type Phase = {
  live: boolean
  opened: boolean
  momentum: boolean
  lastAbs: number
  movement: Point
  velocity: Point
  accelerations: readonly Point[]
  points: readonly { sum: Point; t: number }[]
  merging: readonly Wheel[]
  endsIn: number
}

/** What this event says about the stream. */
export type PhaseRead = {
  /** A stream opened here: the first event, or the hand cutting momentum short. */
  start: boolean
  /** The hand let go ON THIS EVENT. The one moment worth deciding anything at. */
  released: boolean
  /** The device is coasting: this delta is not a person and must move nothing. */
  momentum: boolean
  /** Momentum was interrupted by the hand coming back. */
  interrupted: boolean
  /** px per ms, per axis. */
  velocity: Point
  /** Total travel since the stream opened. */
  movement: Point
  /** Call the stream over after this long with no event. Adapts to the device's own
   *  rate, so a 120 Hz trackpad is not held to a slow mouse's window. */
  endsIn: number
}

const clamp = (v: number) => Math.min(DELTA_MAX, Math.max(-DELTA_MAX, v))
const add = (a: Point, b: Point): Point => ({ x: a.x + b.x, y: a.y + b.y })
const absMax = (p: Point) => Math.max(Math.abs(p.x), Math.abs(p.y))

export function phaseStart(): Phase {
  return {
    live: false,
    opened: false,
    momentum: false,
    lastAbs: Number.POSITIVE_INFINITY,
    movement: { x: 0, y: 0 },
    velocity: { x: 0, y: 0 },
    accelerations: [],
    points: [],
    merging: [],
    endsIn: ENDS_IN_DEFAULT,
  }
}

/** Every acceleration factor of the last ANALYZE merged points reads as a model
 *  coasting: both axes inside the decay band (a still axis reads 0 and abstains), or
 *  both decaying at exactly the same rate, which a hand does not do. */
function coasting(accelerations: readonly Point[]): boolean {
  if (accelerations.length < ANALYZE) return false
  return accelerations.slice(-ANALYZE).every((a) => {
    const inBand = (v: number) => v === 0 || (v >= ACC_MIN && v <= ACC_MAX)
    const locked = a.x === a.y && a.x < 1 && a.x !== 0
    return locked || (inBand(a.x) && inBand(a.y))
  })
}

/** The window to wait before calling the stream over, from the device's own event
 *  rate. Doubled while the hand may still be on the glass: ending a live gesture
 *  early is far worse than ending a coast late. */
function endsIn(deltaTime: number, momentum: boolean): number {
  const base = Math.ceil(deltaTime / 10) * 10 * 1.2
  return Math.min(
    ENDS_IN_MAX,
    Math.round(momentum ? base : Math.max(100, base * 2)),
  )
}

/** One wheel event. Deltas arrive in px (the caller resolves deltaMode). */
export function phaseFeed(
  p: Phase,
  e: Wheel,
): { phase: Phase; read: PhaseRead } {
  const delta = { x: clamp(e.dx), y: clamp(e.dy) }
  const reach = absMax(delta)
  // The hand came back mid-coast: this event opens a new stream, and the old one is
  // reported interrupted so its decision is not taken twice.
  const interrupted =
    p.live && p.momentum && reach > Math.max(2, p.lastAbs * HAND_RETURN)
  let s = !p.live || interrupted ? { ...phaseStart(), live: true } : p

  s = {
    ...s,
    lastAbs: reach,
    movement: add(s.movement, delta),
    merging: [...s.merging, { dx: delta.x, dy: delta.y, t: e.t }],
  }

  let released = false
  if (s.merging.length === MERGE) {
    // A merged point: the pair's total travel at the pair's mean time.
    const sum = s.merging.reduce<Point>(
      (acc, w) => add(acc, { x: w.dx, y: w.dy }),
      { x: 0, y: 0 },
    )
    const t = s.merging.reduce((acc, w) => acc + w.t, 0) / s.merging.length
    const prev = s.points[0]
    let next = s
    if (prev && t > prev.t) {
      const dt = t - prev.t
      const velocity = { x: sum.x / dt, y: sum.y / dt }
      // The ratio to the previous velocity IS the signal. A zero previous velocity
      // divides by one so a still axis reads 0 and abstains rather than exploding.
      const acceleration = {
        x: velocity.x / (s.velocity.x || 1),
        y: velocity.y / (s.velocity.y || 1),
      }
      const accelerations = [...s.accelerations, acceleration].slice(-ANALYZE)
      const momentum = s.momentum || coasting(accelerations)
      released = momentum && !s.momentum
      next = {
        ...s,
        velocity,
        accelerations,
        momentum,
        endsIn: endsIn(dt, momentum),
      }
    }
    s = { ...next, points: [{ sum, t }], merging: [] }
  } else if (!s.opened) {
    // Before a pair exists there is no ratio to take: velocity is this event's travel
    // over the window we would have waited anyway, which is the right order.
    const w = s.merging[s.merging.length - 1] as Wheel
    s = { ...s, velocity: { x: w.dx / s.endsIn, y: w.dy / s.endsIn } }
  }

  const start = !s.opened
  s = { ...s, opened: true }
  return {
    phase: s,
    read: {
      start,
      released,
      momentum: s.momentum,
      interrupted,
      velocity: s.velocity,
      movement: s.movement,
      endsIn: s.endsIn,
    },
  }
}

// The wheel session, framework-free. Three axes, all of them the POSE: a ctrl-wheel
// zoom, a pan while zoomed, and the vertical drag that dismisses. Each offsets the
// pose the hand found (`grab`) and lets silence decide where it lands, which is safe
// because each springs back to a resting place, so a mistimed release costs nothing.
//
// There is no horizontal axis. Sideways wheel belongs to the track, and the track is
// a real scroll container: the browser knows when the fingers left the trackpad and
// we do not, so it owns the momentum and the snap. The binder simply does not
// preventDefault a sideways wheel at fit.
//
// `last` is the accepted tick the velocity span is measured against; `at` the last
// cursor; `live` whether a vertical session ever passed the inertia guard. Ticks in,
// a session and effects out; the binder owns the timers and applies the effects.
// `bun scripts/examples/lightbox-wheel.ts`.

import {
  type Band,
  wheelTick as boundTick,
  clampPan,
  dismissCommit,
  dragProgress,
  dragScale,
  overshoot,
  type Point,
  type Pose,
  panBounds,
  rawPan,
  rubber,
  type Sample,
  type Size,
  type View,
  velocity,
  WHEEL_ZOOM,
  wheelIsHand,
  wheelPx,
  zoomAt,
} from "@/registry/base-nova/lib/lightbox-motion"
import {
  type Phase,
  phaseFeed,
  phaseStart,
} from "@/registry/base-nova/lib/lightbox-wheel-phase"

/** `pass`: the guard rejected this stream (it opened on a coast), so it is ignored
 *  whole. `dead`: the lightbox is leaving, nothing that follows can mean anything. */
export type WheelAxis = "zoom" | "pan" | "y" | "pass" | "dead"

export type WheelSession = {
  axis: WheelAxis
  live: boolean
  /** The first raw vertical ticks, for the inertia guard. */
  ticks: readonly number[]
  x: number
  y: number
  grab: Pose
  /** The grab read back through the pan rubber. */
  raw0: Point
  /** The raw scale the ticks accumulated; the pose wears it rubbered. */
  zoom: number
  samples: readonly Sample[]
  last: number
  at: Point
  /** Hand or coast. The dismiss drag reads it to decide the moment the hand lets go
   *  instead of waiting out the tail. */
  phase: Phase
}

/** One wheel event, in the band's frame. */
export type WheelInput = {
  deltaX: number
  deltaY: number
  deltaMode: number
  ctrl: boolean
  /** The cursor relative to the band center. */
  at: Point
  now: number
}

/** What the engine knows at this tick. */
export type WheelCtx = {
  pose: Pose
  fitted: Size
  band: Band
  zoomMax: number
  /** The visual viewport's height: the dismiss drag's scale. */
  vh: number
  /** The media is a frame: nothing to zoom. */
  frame: boolean
}

export type WheelEffect =
  /** The hand took the image: the engine pauses flights and marks the gesture. */
  | { kind: "grab" }
  /** The hand is done and what follows is only decay: the chrome comes back NOW,
   *  not when the tail finally dies. */
  | { kind: "release" }
  | { kind: "pose"; pose: Pose }
  | { kind: "exit"; vy: number }

/** A sideways wheel at fit is the scroll container's, not ours: no session opens and
 *  the binder leaves the event alone so the browser scrolls, snaps and carries the
 *  momentum itself. */
export function wheelIsTrack(input: WheelInput, ctx: WheelCtx): boolean {
  return (
    !input.ctrl &&
    ctx.pose.s <= 1.01 &&
    Math.abs(input.deltaX) > Math.abs(input.deltaY)
  )
}

const begin = (input: WheelInput, ctx: WheelCtx, phase: Phase) => {
  const axis: WheelAxis = input.ctrl ? "zoom" : ctx.pose.s > 1.01 ? "pan" : "y"
  if (axis === "zoom" && ctx.frame) return null
  const session: WheelSession = {
    axis,
    live: axis !== "y",
    ticks: [],
    x: 0,
    y: 0,
    grab: ctx.pose,
    raw0: rawPan(ctx.pose, ctx.fitted, ctx.band),
    zoom: ctx.pose.s,
    samples: [],
    last: 0,
    at: input.at,
    phase,
  }
  // A vertical session grabs only once the inertia guard has let it through.
  const effects: WheelEffect[] = axis === "y" ? [] : [{ kind: "grab" }]
  return { session, effects }
}

/** A tick: a null session starts one (or refuses: a zoom on a frame), a decided one
 *  ignores the coast that follows, a live one moves the content. Lines and pages
 *  become px here; the guard reads the tick the device sent, motion reads it
 *  bounded. Every event is fed to the phase detector first, session or no session,
 *  because the hand returning mid-coast is what opens the next one. */
export function wheelTick(
  session: WheelSession | null,
  input: WheelInput,
  ctx: WheelCtx,
): { session: WheelSession | null; effects: WheelEffect[] } {
  const rawY = wheelPx(input.deltaY, input.deltaMode, ctx.band.h)
  const dy = boundTick(rawY)
  const fed = phaseFeed(session ? session.phase : phaseStart(), {
    dx: wheelPx(input.deltaX, input.deltaMode, ctx.band.h),
    dy: rawY,
    t: input.now,
  })
  // The hand came back while the device was still coasting: the old session is over
  // and this event opens a new one, from wherever the pose now is.
  const live = session && !fed.read.interrupted ? session : null
  const opened = live
    ? { session: { ...live, phase: fed.phase }, effects: [] }
    : begin(input, ctx, fed.phase)
  if (!opened) return { session: null, effects: [] }
  const effects: WheelEffect[] = opened.effects
  let w = { ...opened.session, phase: fed.phase }
  const axis = w.axis
  if (axis === "dead" || axis === "pass") return { session: w, effects }
  w = { ...w, last: input.now, at: input.at }
  switch (axis) {
    case "zoom": {
      // The raw accumulator rubbers (soft floor under fit, stiff over the ceiling),
      // the way a drag offsets from its grab.
      w = { ...w, zoom: w.zoom * Math.exp(-dy * WHEEL_ZOOM) }
      const v = zoomAt(ctx.pose, rubber(w.zoom, 1, ctx.zoomMax), w.at)
      effects.push({ kind: "pose", pose: { ...v, p: ctx.pose.p } })
      return { session: w, effects }
    }
    case "pan": {
      const b = panBounds(ctx.pose, ctx.fitted, ctx.band)
      const dx = boundTick(wheelPx(input.deltaX, input.deltaMode, ctx.band.h))
      w = { ...w, x: w.x - dx, y: w.y - dy }
      effects.push({
        kind: "pose",
        pose: {
          ...ctx.pose,
          x: overshoot(w.raw0.x + w.x, b.x),
          y: overshoot(w.raw0.y + w.y, b.y),
        },
      })
      return { session: w, effects }
    }
    case "y": {
      // Nothing accumulates before the guard decides: a session it rejects is passed
      // through whole, one it accepts starts from its first applied tick, offsetting
      // the pose it finds there.
      if (!w.live) {
        const ticks = [...w.ticks, Math.abs(rawY)]
        w = { ...w, ticks }
        if (ticks.length < 3) return { session: w, effects }
        if (!wheelIsHand(ticks))
          return { session: { ...w, axis: "pass" }, effects }
        effects.push({ kind: "grab" })
        w = { ...w, live: true, grab: ctx.pose }
      }
      w = { ...w, y: w.y - dy }
      const g = w.grab
      effects.push({
        kind: "pose",
        pose: {
          x: g.x,
          y: g.y + w.y,
          s: g.s * dragScale(w.y, ctx.vh),
          p: g.p * dragProgress(w.y, ctx.vh),
        },
      })
      w = { ...w, samples: [...w.samples, { x: 0, y: w.y, t: input.now }] }
      const v = velocity(w.samples, input.now)
      if (dismissCommit(w.y, v.y, ctx.vh)) {
        w = { ...w, axis: "dead" }
        effects.push({ kind: "release" }, { kind: "exit", vy: v.y })
      }
      return { session: w, effects }
    }
    default: {
      const never: never = axis
      throw new Error(`lightbox: wheel axis ${String(never)}`)
    }
  }
}

export type WheelRelease =
  | { kind: "none" }
  /** Zoom let go under fit: spring back to fit. A wheel never dismisses. */
  | { kind: "fit" }
  /** Zoom let go: undo the rubber at the cursor, then momentum and clamp. */
  | { kind: "zoom"; at: Point }
  /** Pan let go: back inside the bounds. */
  | { kind: "pan"; target: View }
  /** A dismiss drag that did not commit: home under the hand's spring, with its speed. */
  | { kind: "cancel"; vel: Point }

/** The stream stopped: the session ends and decides where the pose lands. */
export function wheelRelease(
  w: WheelSession,
  ctx: Pick<WheelCtx, "pose" | "fitted" | "band">,
): WheelRelease {
  const v = velocity(w.samples, w.last)
  switch (w.axis) {
    case "pass":
    case "dead":
      return { kind: "none" }
    case "zoom":
      return ctx.pose.s < 1 ? { kind: "fit" } : { kind: "zoom", at: w.at }
    case "pan":
      return { kind: "pan", target: clampPan(ctx.pose, ctx.fitted, ctx.band) }
    case "y":
      return w.live ? { kind: "cancel", vel: v } : { kind: "none" }
    default: {
      const never: never = w.axis
      throw new Error(`lightbox: wheel axis ${String(never)}`)
    }
  }
}

// The pointer state machine, framework-free. Points in, a new state and effects out;
// the binder owns capture, the DOM and the clock. `samples` hold ONE trajectory: the
// finger, or the pinch midpoint; the span is emptied whenever the pointer count
// changes. `anchor` is the last point the hand was at, relative to the band center:
// where a rubbered zoom is undone. `raw0` is the grab read back through the pan
// rubber: a drag offsets it and rubbers the sum, so a grab taken mid-bounce moves
// under the finger from its first px. `bun scripts/examples/lightbox-gesture.ts`.

import {
  type Band,
  clampPan,
  DOUBLE_MOUSE,
  DOUBLE_TOUCH,
  DOUBLE_TRAVEL,
  dismissCommit,
  dragProgress,
  dragScale,
  INTENT,
  overshoot,
  PINCH_CLOSE,
  PINCH_PASSED,
  type Point,
  type Pose,
  panBounds,
  pinchProgress,
  project,
  RELOCK,
  rawPan,
  rubber,
  SAMPLES,
  type Sample,
  type Size,
  TAP_TRAVEL,
  type View,
  velocity,
  zoomAt,
} from "@/registry/base-nova/lib/lightbox-motion"

export type Gesture = {
  /** Live pointers, by id, in client px. */
  pts: ReadonlyMap<number, Point>
  start: Sample
  samples: readonly Sample[]
  prev: Point
  grab: Pose
  raw0: Point
  axis: "x" | "y" | null
  mode: "pan" | "fit"
  pinch: { s0: number; p0: number; d0: number; mid0: Point; view0: View } | null
  pinched: boolean
  pinchMax: number
  anchor: Point
  onMedia: boolean
  type: string
}

/** One pointer event, with the band-relative point the binder computed. */
export type PointerInput = {
  id: number
  /** Client px. */
  x: number
  y: number
  /** `at` relative to the band center. */
  at: Point
  t: number
  type: string
  onMedia: boolean
  /** Coalesced positions of this move, oldest first; the move itself when empty. */
  hand?: readonly Sample[]
  /** The pinch midpoint relative to the band center; the binder measures it because
   *  only it knows where the band sits on screen. */
  mid?: Point
}

export type GestureCtx = {
  pose: Pose
  fitted: Size
  band: Band
  zoomMax: number
  vh: number
  /** The media cannot be zoomed or pinched (a frame). */
  frame: boolean
}

export type GestureEffect =
  /** Read the flight at its clock and drop it: the pinch or the relock starts live. */
  | { kind: "sync" }
  | { kind: "pose"; pose: Pose }
  /** Drag the scroll container by this many px (a mouse only; see gestureMove). */
  | { kind: "scroll"; dx: number }
  /** The image flies back to the grab while the track takes the hand; settles nothing. */
  | { kind: "unpose"; target: Pose }
  | { kind: "trace"; text: string }

const push = (samples: readonly Sample[], s: Sample): Sample[] => {
  const next = [...samples, s]
  return next.length > SAMPLES ? next.slice(next.length - SAMPLES) : next
}

const dist = (pts: ReadonlyMap<number, Point>) => {
  const [a, b] = [...pts.values()] as [Point, Point]
  return Math.hypot(a.x - b.x, a.y - b.y)
}
export const midOf = (pts: ReadonlyMap<number, Point>): Point => {
  const [a, b] = [...pts.values()] as [Point, Point]
  return { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 }
}

/** A pointer went down: a new gesture, or another finger on the live one. A second
 *  finger opens the pinch, computed FROM the pose, so the binder syncs first. */
export function gestureDown(
  g: Gesture | null,
  input: PointerInput,
  ctx: GestureCtx,
): { gesture: Gesture; effects: GestureEffect[] } {
  const effects: GestureEffect[] = []
  let next: Gesture
  if (g) {
    next = {
      ...g,
      pts: new Map(g.pts).set(input.id, { x: input.x, y: input.y }),
    }
    effects.push({
      kind: "trace",
      text: `down ${input.type} #${input.id} +finger`,
    })
  } else {
    const mode: Gesture["mode"] = ctx.pose.s > 1.01 ? "pan" : "fit"
    next = {
      pts: new Map([[input.id, { x: input.x, y: input.y }]]),
      start: { x: input.x, y: input.y, t: input.t },
      samples: [],
      prev: { x: input.x, y: input.y },
      grab: ctx.pose,
      raw0: rawPan(ctx.pose, ctx.fitted, ctx.band),
      axis: null,
      mode,
      pinch: null,
      pinched: false,
      pinchMax: ctx.pose.s,
      anchor: input.at,
      onMedia: input.onMedia,
      type: input.type,
    }
    effects.push({
      kind: "trace",
      text: `down ${input.type} #${input.id} ${mode} ${input.onMedia ? "media" : "backdrop"}`,
    })
  }
  if (next.pts.size === 2 && !ctx.frame) {
    // The pinch is computed FROM the pose: a flight in progress (the y-to-x relock)
    // is read and dropped first, so s0 and view0 are the live pose.
    effects.push({ kind: "sync" })
    next = {
      ...next,
      pinch: {
        s0: ctx.pose.s,
        p0: ctx.pose.p,
        d0: dist(next.pts),
        mid0: input.mid ?? { x: 0, y: 0 },
        view0: ctx.pose,
      },
      pinched: true,
      axis: null,
      samples: [],
    }
    effects.push({ kind: "trace", text: "pinch start" })
  }
  return { gesture: next, effects }
}

/** A move: the pinch follows the fingers, a pan offsets the rubbered grab, and a
 *  single finger at fit locks an axis at INTENT and relocks at RELOCK. */
export function gestureMove(
  g: Gesture,
  input: PointerInput,
  ctx: GestureCtx,
): { gesture: Gesture; effects: GestureEffect[] } {
  const effects: GestureEffect[] = []
  let next: Gesture = {
    ...g,
    pts: new Map(g.pts).set(input.id, { x: input.x, y: input.y }),
  }
  const pinch = next.pinch
  if (pinch && next.pts.size >= 2) {
    const ms = midOf(next.pts)
    next = {
      ...next,
      samples: push(next.samples, { x: ms.x, y: ms.y, t: input.t }),
    }
    const raw = (pinch.s0 * dist(next.pts)) / pinch.d0
    next = { ...next, pinchMax: Math.max(next.pinchMax, raw) }
    // From fit, pinching in is the dismiss gesture and follows the fingers, lighting
    // the room, the same rule the release closes by; a pinch that went past the
    // ceiling first, or one from a zoom, rubbers under 1 and springs back, the room
    // untouched.
    const dismissing =
      pinch.s0 <= 1.01 && raw < 1 && next.pinchMax < PINCH_PASSED
    const s = dismissing ? raw : rubber(raw, 1, ctx.zoomMax)
    const m = input.mid ?? next.anchor
    next = { ...next, anchor: m }
    const v = zoomAt(pinch.view0, s, pinch.mid0)
    // A pinch that starts mid-drag carries the drag's darkness: p never jumps.
    effects.push({
      kind: "pose",
      pose: {
        x: v.x + m.x - pinch.mid0.x,
        y: v.y + m.y - pinch.mid0.y,
        s,
        p: dismissing ? Math.min(pinch.p0, pinchProgress(s)) : pinch.p0,
      },
    })
    return { gesture: next, effects }
  }
  if (next.pts.size !== 1) return { gesture: next, effects }
  for (const s of input.hand ?? [{ x: input.x, y: input.y, t: input.t }])
    next = { ...next, samples: push(next.samples, s) }
  next = { ...next, anchor: input.at }
  const dx = input.x - next.start.x
  const dy = input.y - next.start.y
  const mx = input.x - next.prev.x
  const my = input.y - next.prev.y
  next = { ...next, prev: { x: input.x, y: input.y } }
  if (next.mode === "pan") {
    const b = panBounds(next.grab, ctx.fitted, ctx.band)
    effects.push({
      kind: "pose",
      pose: {
        ...next.grab,
        x: overshoot(next.raw0.x + dx, b.x),
        y: overshoot(next.raw0.y + dy, b.y),
      },
    })
    return { gesture: next, effects }
  }
  // The finger left after a pinch drifts a few px: that is never a drag.
  if (next.axis === null) {
    if (Math.abs(dx) + Math.abs(dy) < INTENT) return { gesture: next, effects }
    const axis = next.pinched || Math.abs(dx) <= Math.abs(dy) ? "y" : "x"
    next = { ...next, axis }
    if (axis === "y") effects.push({ kind: "trace", text: "axis y" })
  } else if (
    next.axis === "x" &&
    Math.abs(my) > RELOCK &&
    Math.abs(my) > 3 * Math.abs(mx)
  ) {
    next = { ...next, axis: "y" }
    effects.push({ kind: "trace", text: "axis y" }, { kind: "sync" })
  } else if (
    next.axis === "y" &&
    !next.pinched &&
    Math.abs(mx) > RELOCK &&
    Math.abs(mx) > 3 * Math.abs(my)
  ) {
    next = { ...next, axis: "x" }
    effects.push(
      { kind: "trace", text: "axis x (relock)" },
      { kind: "unpose", target: next.grab },
    )
  }
  if (next.axis === "y") {
    effects.push({
      kind: "pose",
      pose: {
        x: next.grab.x,
        y: next.grab.y + dy,
        s: next.grab.s * dragScale(dy, ctx.vh),
        p: next.grab.p * dragProgress(dy, ctx.vh),
      },
    })
  } else {
    // Sideways is the track's, and the track is a scroll container. A finger never
    // gets here (touch-action hands horizontal panning straight to the browser); a
    // MOUSE does, and it drags the scroller by the same amount, so the platform's
    // own snap decides where it lands.
    effects.push({ kind: "scroll", dx: mx })
  }
  return { gesture: next, effects }
}

export type GestureRelease =
  /** Fingers remain: the gesture regrabs around the one left. */
  | { kind: "hold"; gesture: Gesture }
  /** A pinch let go under the close rule: leave, with the hand's velocity. */
  | { kind: "exit"; vel: Point }
  /** A pinch or a dismiss that did not commit: home under the hand's spring.
   *  `zoomed` when a pinch let go under fit, the one case React still reads 1. */
  | { kind: "cancel"; vel: Point; zoomed: boolean }
  /** A pinch over fit: undo the rubber at the anchor, then momentum and clamp. */
  | { kind: "zoom"; vel: Point; at: Point }
  /** Nothing moved far enough to be a drag. */
  | { kind: "tap"; at: Point; x: number; y: number; t: number }
  /** A pan flick: coast, and bounce off whichever wall cuts it short. */
  | { kind: "coast"; coast: View; target: View; vel: Point }
  /** An axis was locked but the release decides nothing: resume what was flying. */
  | { kind: "resume" }
  /** A mouse let the track go: hand it back to the platform's snap. */
  | { kind: "snap" }

/** A pointer lifted (or cancelled). The release instant is the clock, not a sample:
 *  a hand held still before lifting reads as stopped, a mouse button lifting late
 *  keeps the hand's speed. */
export function gestureUp(
  g: Gesture,
  input: PointerInput,
  ctx: GestureCtx,
): GestureRelease {
  const pts = new Map(g.pts)
  pts.delete(input.id)
  if (pts.size === 1) {
    const [p] = [...pts.values()] as [Point]
    return {
      kind: "hold",
      gesture: {
        ...g,
        pts,
        pinch: null,
        samples: [],
        grab: ctx.pose,
        raw0: rawPan(ctx.pose, ctx.fitted, ctx.band),
        start: { x: p.x, y: p.y, t: input.t },
        prev: p,
        axis: null,
        mode: ctx.pose.s > 1.01 ? "pan" : "fit",
      },
    }
  }
  if (pts.size > 0) return { kind: "hold", gesture: { ...g, pts } }
  const v = velocity(g.samples, input.t)
  if (g.pinched) {
    const s = ctx.pose.s
    if (s < PINCH_CLOSE && g.pinchMax < PINCH_PASSED)
      return { kind: "exit", vel: v }
    if (s < 1) return { kind: "cancel", vel: v, zoomed: true }
    return { kind: "zoom", vel: v, at: g.anchor }
  }
  const travel = Math.hypot(input.x - g.start.x, input.y - g.start.y)
  if (g.axis === null && travel < TAP_TRAVEL)
    return { kind: "tap", at: input.at, x: input.x, y: input.y, t: input.t }
  // A pan has no axis (it moves on both): its release is the coast, before the axis
  // test, or a flick would resume a stale aim and stop dead past the bound.
  if (g.mode === "pan") {
    const coast = {
      x: project(ctx.pose.x, v.x),
      y: project(ctx.pose.y, v.y),
      s: ctx.pose.s,
    }
    return {
      kind: "coast",
      coast,
      target: clampPan(coast, ctx.fitted, ctx.band),
      vel: v,
    }
  }
  if (g.axis === null) return { kind: "resume" }
  if (g.axis === "y") {
    // The rule is about drag distance: mid-fly the absolute y still holds the source
    // offset, so the delta from the grab is what is tested. The axis is locked:
    // lateral hand speed never reaches the spring.
    const vy = { x: 0, y: v.y }
    return dismissCommit(ctx.pose.y - g.grab.y, v.y, ctx.vh)
      ? { kind: "exit", vel: vy }
      : { kind: "cancel", vel: vy, zoomed: false }
  }
  return { kind: "snap" }
}

export type TapIntent =
  /** Nothing but settle what was flying. */
  | { kind: "settle" }
  | { kind: "escape" }
  | { kind: "zoom"; at: Point }
  | { kind: "chrome" }
  /** A finger's first tap at fit: the chrome toggles unless a second tap lands. */
  | { kind: "wait"; ms: number }

/** The tap ladder. `last` is the previous tap of this session (the binder holds it,
 *  and clears it when the wait fires). A pointer with a cursor is told what a click
 *  does (zoom-in, zoom-out): one click toggles the zoom at the point, and the second
 *  click of a double click is the same intent, already served. A finger has no
 *  cursor: one tap toggles the chrome, two toggle the zoom. */
export function tapIntent(
  last: Sample | null,
  tap: { at: Point; x: number; y: number; t: number; type: string },
  g: Pick<Gesture, "onMedia">,
  ctx: Pick<GestureCtx, "pose"> & { kind: string },
): { last: Sample | null; intents: TapIntent[] } {
  const keep = { x: tap.x, y: tap.y, t: tap.t }
  if (!g.onMedia)
    return {
      last: null,
      intents: [ctx.pose.s <= 1.01 ? { kind: "escape" } : { kind: "settle" }],
    }
  // A tap on a video is the video's (its controls, the platform's play toggle); a
  // tap on a frame is the frame's.
  if (ctx.kind === "video" || ctx.kind === "frame")
    return { last: null, intents: [{ kind: "settle" }] }
  const span = tap.type === "touch" ? DOUBLE_TOUCH : DOUBLE_MOUSE
  const again =
    last !== null &&
    tap.t - last.t < span &&
    Math.hypot(tap.x - last.x, tap.y - last.y) < DOUBLE_TRAVEL
  if (tap.type !== "touch") {
    if (again) return { last: null, intents: [{ kind: "settle" }] }
    return { last: keep, intents: [{ kind: "zoom", at: tap.at }] }
  }
  if (again) return { last: null, intents: [{ kind: "zoom", at: tap.at }] }
  return {
    last: keep,
    intents:
      ctx.pose.s <= 1.01
        ? [{ kind: "wait", ms: DOUBLE_TOUCH }, { kind: "settle" }]
        : [{ kind: "settle" }],
  }
}
